'''
A development tool for removing autogenerated files.

Usage: uv run clean.py [mode] [*params (if required)]

Modes:
    * clean | -c | (default) - remove generated files
      params: None
    * start | -s - remove generated files and start a program
      params: 
        target - executable file (.py or .exe)
'''

import os
import sys
import time

import loc



def clean_config():
    config_file = loc.settings
    if os.path.exists(config_file):
        os.remove(config_file)


def clean_start():
    if len(sys.argv) < 3:
        print('Missing execution target!')
        sys.exit()
    
    target = sys.argv[2]
    match target.split('.')[-1]:
        case 'py':
            cmd = "uv run " + sys.argv[2]
        case 'exe':
            cmd = target
        case _:
            print('Invalid execution target!')
            sys.exit()

    clean_config()
    time.sleep(0.3)
    os.system(cmd)


def read_mode():
    if len(sys.argv) < 2:
        return ''
    return sys.argv[1]



if __name__ == "__main__":
    match read_mode():
        case '' | 'clean' | '-c':
            clean_config()
        case 'start' | '-s':
            clean_start()